/* ---------- Hijri conversion & wasal-anniversary helpers ---------- */
/* Har mulk ki Ruet-e-Hilal (chaand dikhne ki) announcement alag hoti hai, is liye
   ek hi Gregorian din ko different mulk kabhi kabhi alag Hijri tareekh maante hain.
   Base calculation Umm al-Qura (Saudi) calendar par hai; owner apna mulk select
   karke ya manually ±din adjust karke isay apni mulk ki announcement se match kar
   sakta hai. Yehi adjustment Wasal ki Hijri tareekh aur Barsi alert dono par lagta hai. */
const HIJRI_COUNTRIES = [
  {code:'PK', label:'Pakistan',        adjust:-1},
  {code:'SA', label:'Saudi Arabia (Umm al-Qura)', adjust:0},
  {code:'IN', label:'India',           adjust:-1},
  {code:'BD', label:'Bangladesh',      adjust:-1},
  {code:'AE', label:'UAE / Gulf',      adjust:0},
  {code:'TR', label:'Turkey',          adjust:0},
  {code:'ID', label:'Indonesia',       adjust:-1},
  {code:'MY', label:'Malaysia',        adjust:-1},
  {code:'OTHER', label:'Other / Manual', adjust:0},
];
function hijriAdjustDays(){ return (DB.config && DB.config.hijriAdjustDays) || 0; }
function shiftDays(dateObj, days){ return new Date(dateObj.getTime() + days*86400000); }
/* Gregorian date -> Hijri, computed with plain arithmetic (civil/tabular Islamic calendar).
   We used to ask the browser to do this via Intl.DateTimeFormat(..., 'u-ca-islamic-umalqura'),
   but that silently depends on the device's ICU data: desktop Chrome/Edge ship the full
   Islamic-calendar tables, while many Android WebViews (the ones used inside file-manager /
   note-taking apps, not full Chrome) don't — and instead of throwing an error, they quietly
   fall back to the Gregorian calendar, so the "Hijri" date shown was actually just the
   Gregorian date again. Computing it ourselves removes that dependency entirely, so the
   result is identical on every device. (Being a tabular calendar, it can land a day or two
   off the official Umm al-Qura sighting-based date — that's what the Adjustment setting
   below is for.) */
const HIJRI_MONTHS = ['Muharram','Safar',"Rabi' al-Awwal","Rabi' al-Thani",'Jumada al-Awwal','Jumada al-Thani','Rajab',"Sha'ban",'Ramadan','Shawwal',"Dhu al-Qi'dah",'Dhu al-Hijjah'];
function gregorianToJDN(y,m,d){
  const a = Math.floor((14-m)/12);
  const y2 = y + 4800 - a;
  const m2 = m + 12*a - 3;
  return d + Math.floor((153*m2+2)/5) + 365*y2 + Math.floor(y2/4) - Math.floor(y2/100) + Math.floor(y2/400) - 32045;
}
function jdnToHijriParts(jdn){
  const epoch = 1948440;
  let l = jdn - epoch + 10632;
  const n = Math.floor((l-1)/10631);
  l = l - 10631*n + 354;
  const j = Math.floor((10985-l)/5316)*Math.floor((50*l)/17719) + Math.floor(l/5670)*Math.floor((43*l)/15238);
  l = l - Math.floor((30-j)/15)*Math.floor((17719*j)/50) - Math.floor(j/16)*Math.floor((15238*j)/43) + 29;
  const month = Math.floor((24*l)/709);
  const day = l - Math.floor((709*month)/24);
  const year = 30*n + j - 30;
  return {day, month, year};
}
function toHijri(isoDate){
  if(!isoDate) return '';
  const d = shiftDays(new Date(isoDate+'T12:00:00'), hijriAdjustDays());
  const {day, month, year} = jdnToHijriParts(gregorianToJDN(d.getFullYear(), d.getMonth()+1, d.getDate()));
  if(!day || !month || !year) return '';
  return `${day} ${HIJRI_MONTHS[month-1]}, ${year} AH`;
}
function hijriParts(dateObj){
  const shifted = shiftDays(dateObj, hijriAdjustDays());
  const o = jdnToHijriParts(gregorianToJDN(shifted.getFullYear(), shifted.getMonth()+1, shifted.getDate()));
  return (o.day && o.month && o.year) ? o : null;
}
/* Owner ke config.anniversaryFormat ke mutabiq — 'hijri' select hai tu Agli Barsi
   Hijri calendar ki usi tareekh (month/day) par aayegi jis din Marhoom ka wasal hua tha,
   chahe Gregorian mein wo date har saal ~10-11 din peechay hi kyun na aaye.
   'gregorian' select hai tu Gregorian month/day par hi (jaisa pehlay tha). */
function nextAnniversary(isoDod){
  if(!isoDod) return null;
  const d = new Date(isoDod+'T12:00:00');
  const now = new Date();
  const todayOnly = new Date(now.getFullYear(), now.getMonth(), now.getDate());
  if(DB.config.anniversaryFormat === 'hijri'){
    const dodH = hijriParts(d);
    if(dodH){
      for(let i=0;i<370;i++){
        const cand = new Date(todayOnly.getFullYear(), todayOnly.getMonth(), todayOnly.getDate()+i);
        const candH = hijriParts(cand);
        if(candH && candH.month===dodH.month && candH.day===dodH.day) return cand;
      }
    }
  }
  let next = new Date(now.getFullYear(), d.getMonth(), d.getDate());
  if(next < todayOnly) next = new Date(now.getFullYear()+1, d.getMonth(), d.getDate());
  return next;
}
function isAnniversaryToday(isoDod){
  if(!isoDod) return false;
  const d = new Date(isoDod+'T12:00:00');
  const now = new Date();
  if(DB.config.anniversaryFormat === 'hijri'){
    const dodH = hijriParts(d);
    const nowH = hijriParts(now);
    if(dodH && nowH) return dodH.month===nowH.month && dodH.day===nowH.day;
  }
  return d.getMonth()===now.getMonth() && d.getDate()===now.getDate();
}
function formatAnniversaryDate(dateObj){
  if(!dateObj) return '';
  if(DB.config.anniversaryFormat === 'hijri'){
    try{
      const d = shiftDays(dateObj, hijriAdjustDays());
      return new Intl.DateTimeFormat('en-TN-u-ca-islamic-umalqura', {day:'numeric', month:'long', year:'numeric'}).format(d);
    }
    catch(e){ return dateObj.toLocaleDateString(); }
  }
  return dateObj.toLocaleDateString();
}

function wasalBlock(m, s){
  if(!m.dod) return '';
  const hijri = m.dodHijri || toHijri(m.dod);
  const next = nextAnniversary(m.dod);
  const nextStr = next ? formatAnniversaryDate(next) : '';
  const annivToday = isAnniversaryToday(m.dod);
  let banner = '';
  if(annivToday){
    banner = `<div class="anniversary-banner rounded-lg p-3 mt-2 text-sm font-bold" style="background:var(--emerald-pale);color:var(--emerald-deep);border:1px solid var(--gold)">
      🕊️ Aaj <b>${esc(m.name)}</b> ki wasal barsi hai.
      ${s.totalPct>=100 ? ' Alhamdulillah — unki tamam Qaza Namaz mukammal ho chuki hai. Allah unhein maghfirat aur buland darjaat ata farmaye. Ameen 🤲' : ` Abhi ${s.totalRemaining} Qaza Namaz baqi hain — aaj khususi tor par unke liye Qaza ada karein.`}
    </div>`;
  } else if(s.totalPct>=100){
    banner = `<div class="rounded-lg p-3 mt-2 text-sm font-bold" style="background:var(--emerald-pale);color:var(--emerald-deep)">✅ Alhamdulillah — ${esc(m.name)} ki tamam Qaza Namaz mukammal ho chuki hai. Allah qabool farmaye. 🤲</div>`;
  }
  return `<div class="text-xs text-gray-500 mt-1">🕊️ Wasal: ${esc(m.dod)} <span class="text-gray-400">(${esc(hijri)})</span> · Agli Barsi: ${esc(nextStr)}</div>${banner}`;
}
function getActor(){
  if(!SESSION) return null;
  if(SESSION.role==='owner'){
    const acc = DB.config.ownerAccount||{};
    return {id:'owner', name:acc.name||'Family Owner', photo:acc.photo||null};
  }
  const mem = DB.members.find(m=>m.id===SESSION.memberId) || {};
  return {id:mem.id, name:mem.name, photo:mem.photo||null};
}

/* ---------------------------- DEFAULT DB ---------------------------- */
function defaultDB(){
  return {
    config:{
      familyName:'Our Family',
      logo:null,
      ownerAccount:null,   // {name,password,photo} set on first run
      anniversaryFormat:'gregorian',  // 'gregorian' or 'hijri' — which calendar the Barsi alert fires on
      hijriCountry:'PK',      // which country's moon-sighting convention to approximate (default Pakistan)
      hijriAdjustDays:-1      // day-offset applied to the Umm al-Qura calendar for that country
    },
    marhooms:[],   // {id,name,relation,gender,dob(Gregorian),dod(Gregorian),dodHijri,photo,targets:{fajr,zuhr,asr,maghrib,isha}}
    members:[],    // {id,name,relation,password,photo}
    progress:{},   // marhoomId -> actorId('owner' or memberId) -> {fajr,zuhr,asr,maghrib,isha}
    activity:[]    // [{id,ts,marhoomId,memberId,prayer,delta}] most recent first, capped at 300
  };
}
let DB = loadDB();
function loadDB(){
  try{
    const raw = localStorage.getItem(DB_KEY);
    if(!raw) return defaultDB();
    const parsed = JSON.parse(raw);
    const d = defaultDB();
    return Object.assign(d, parsed, {config:Object.assign(d.config, parsed.config||{})});
  }catch(e){ return defaultDB(); }
}
function saveDB(){ localStorage.setItem(DB_KEY, JSON.stringify(DB)); scheduleAutoSync(); }

