/* ---------------------------- SHARED UI HELPERS ---------------------------- */
function card(inner){ return `<div class="card mb-5">${inner}</div>`; }
function ring(pct, size, stroke, label){
  size = size||110; stroke = stroke||10;
  const r=(size-stroke)/2, c=2*Math.PI*r, off=c*(1-Math.min(Math.max(pct,0),100)/100);
  return `<div class="relative" style="width:${size}px;height:${size}px;">
    <svg width="${size}" height="${size}">
      <circle cx="${size/2}" cy="${size/2}" r="${r}" stroke="var(--sand-dark)" stroke-width="${stroke}" fill="none"/>
      <circle cx="${size/2}" cy="${size/2}" r="${r}" stroke="var(--gold)" stroke-width="${stroke}" fill="none"
        stroke-linecap="round" stroke-dasharray="${c}" stroke-dashoffset="${off}"
        transform="rotate(-90 ${size/2} ${size/2})" class="ring-fill"/>
    </svg>
    <div class="absolute inset-0 flex flex-col items-center justify-center">
      <span class="font-bold text-lg" style="color:var(--emerald-deep)">${pct.toFixed(0)}%</span>
      ${label?`<span class="text-[10px] text-gray-500">${esc(label)}</span>`:''}
    </div>
  </div>`;
}
function bar(pct){ return `<div class="bar-track"><div class="bar-fill" style="width:${Math.min(Math.max(pct,0),100)}%"></div></div>`; }

/* ---------------------------- STATS ---------------------------- */
function marhoomStats(marhoomId){
  const m = DB.marhooms.find(x=>x.id===marhoomId);
  if(!m) return null;
  const byMember = DB.progress[marhoomId] || {};
  const perPrayer = {};
  let totalTarget=0, totalDone=0;
  PRAYERS.forEach(p=>{
    const target = Number(m.targets?.[p.key])||0;
    let done=0;
    Object.values(byMember).forEach(rec=>{ done += Number(rec?.[p.key])||0; });
    done = Math.min(done, target || done); // don't let display exceed target visually
    const rawDone = Object.values(byMember).reduce((a,rec)=>a+(Number(rec?.[p.key])||0),0);
    perPrayer[p.key] = {target, done:rawDone, remaining:Math.max(target-rawDone,0), pct: target? Math.min(rawDone/target*100,100):(rawDone>0?100:0)};
    totalTarget += target; totalDone += Math.min(rawDone,target||rawDone);
  });
  const totalPct = totalTarget? Math.min(totalDone/totalTarget*100,100) : 0;
  return {marhoom:m, perPrayer, totalTarget, totalDone, totalRemaining:Math.max(totalTarget-totalDone,0), totalPct};
}
function memberContribution(marhoomId, memberId){
  const rec = (DB.progress[marhoomId]||{})[memberId] || emptyCounts();
  const total = PRAYERS.reduce((a,p)=>a+(Number(rec[p.key])||0),0);
  return {rec, total};
}

