function renderActivityLog(){
  const rows = DB.activity.slice(0,150).map(a=>{
    const m = DB.marhooms.find(x=>x.id===a.marhoomId);
    const mem = DB.members.find(x=>x.id===a.memberId) || DB.config.ownerAccount;
    const prayer = PRAYERS.find(p=>p.key===a.prayer)?.label || a.prayer;
    const who = mem?.name || 'Someone';
    const verb = a.delta>0 ? 'marked' : 'removed';
    const d = new Date(a.ts);
    return `<tr class="border-b table-row">
      <td class="py-2 text-xs text-gray-500 whitespace-nowrap">${d.toLocaleDateString()} ${d.toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'})}</td>
      <td>${esc(who)}</td><td>${a.delta>0?'✅':'↩️'} ${verb} 1 <b>${esc(prayer)}</b> Qaza</td><td>${esc(m?.name||'—')}</td>
    </tr>`;
  }).join('') || `<tr><td colspan="4" class="text-center text-gray-400 py-4">No activity yet.</td></tr>`;
  return card(`
    <h2 class="text-xl font-bold mb-4" style="color:var(--emerald-deep)">📜 Activity Log</h2>
    <div class="overflow-x-auto max-h-[32rem] overflow-y-auto">
    <table class="w-full text-sm">
      <thead><tr class="text-left border-b"><th class="py-2">When</th><th>Who</th><th>What</th><th>For</th></tr></thead>
      <tbody>${rows}</tbody>
    </table>
    </div>
  `);
}

